            default: accept;
        }
    }
    state parse_ipv4 {
        b.extract(hdr.h_ipv4);
        transition select(hdr.h_ipv4.protocol) {
            PROTOCOL_UDP: parse_udp;
            PROTOCOL_TCP: accept;
            default: accept;
        }
    }
    state parse_udp {
        b.extract(hdr.h_udp);
        transition select(hdr.h_udp.dstPort) {
            UDP_PORT: parse_dns;
            TCP_PORT: accept;
            default: accept;
        }
