const bit<16> TYPE_IPV4 = 0x0800;
const bit<16> TYPE_ARP = 0x0806;
const bit<16> TYPE_VLAN = 0x8100;

struct headers {
    ethernet_t eth;
    vlan_t vlan;
    ipv4_t ipv4;
}

parser MyParser(packet_in b, out headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    state start {
        transition parse_ethernet;
    }

    state parse_ethernet {
        hdr.eth.parse(b);
        transition select(hdr.eth.etherType) {
            TYPE_IPV4: parse_ipv4;
            TYPE_ARP: accept;
            default: reject;
        }
    }

    state parse_ipv4 {
        hdr.ipv4.parse(b);
        transition select(hdr.ipv4.protocol) {
            tcp: accept;
            udp: accept;
            icmp: accept;
            igmp: accept;
            default: reject;
        }
    }
}

control MyVerifyChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}

control MyIngress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    action drop() {
        mark_to_drop(stdmeta);
    }

    action set_egress_spec(egressSpec_t port) {
        stdmeta.egress_spec = port;
    }

    table t_forwarding {
        key = {
            hdr.ipv4.dstAddr : exact;
            hdr.vlan.vid : exact;
        }
        actions = {
            set_egress_spec;
            drop;
        }
        size = 1024;
        default_action = drop();
    }

    apply {
        if (hdr.ipv4.isValid()) {
            t_forwarding.apply();
        } else {
            drop();
        }
    }
}

control MyEgress(inout headers hdr, inout metadata meta, inout standard_metadata_t stdmeta) {
    apply { }
}

control MyComputeChecksum(inout headers hdr, inout metadata meta) {
    apply { }
}

control MyDeparser(packet_out b, in headers hdr) {
    apply {
        hdr.eth.emit(b);
        hdr.ipv4.emit(b);
        hdr.vlan.emit(b);
    }
}

V1Switch(MyParser(),
         MyVerifyChecksum(),
         MyIngress(),
         MyEgress(),
         MyComputeChecksum(),
         MyDeparser()) main;

